import{_ as e,o as i,c as t,aA as o}from"./chunks/framework.Dl8a02nG.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"demos/overviews/biosemi_import.md","filePath":"demos/overviews/biosemi_import.md","lastUpdated":null}'),r={name:"demos/overviews/biosemi_import.md"};function l(n,a,s,d,p,c){return i(),t("div",null,[...a[0]||(a[0]=[o('<p>This demo demonstrates importing BioSemi BDF files into EegFun.jl.</p><h3 id="What-is-BioSemi-BDF-Format?" tabindex="-1">What is BioSemi BDF Format? <a class="header-anchor" href="#What-is-BioSemi-BDF-Format?" aria-label="Permalink to &quot;What is BioSemi BDF Format? {#What-is-BioSemi-BDF-Format?}&quot;">​</a></h3><p>BioSemi is a popular manufacturer of active electrode EEG systems. The BDF (BioSemi Data Format) is a 24-bit variant of the European Data Format (EDF) designed specifically for BioSemi&#39;s ActiveTwo and ActiveOne systems.</p><p><strong>Key features</strong>:</p><ul><li><p>24-bit resolution for high-precision recordings</p></li><li><p>Continuous raw data storage</p></li><li><p>Trigger channel for event markers</p></li><li><p>Standard format widely supported across analysis tools</p></li></ul><h3 id="Import-Capabilities" tabindex="-1">Import Capabilities <a class="header-anchor" href="#Import-Capabilities" aria-label="Permalink to &quot;Import Capabilities {#Import-Capabilities}&quot;">​</a></h3><p><strong>Data loading</strong>:</p><ul><li><p>Raw continuous EEG time series (24-bit precision)</p></li><li><p>Sampling rate and channel metadata</p></li><li><p>Trigger/event markers (encoded in Status channel)</p></li></ul><p><strong>What you need</strong>:</p><ul><li><p><code>.bdf</code> file (contains all data)</p></li><li><p>Electrode layout file matching your cap configuration</p></li><li><p>BioSemi systems typically use standard cap layouts (16, 32, 64, 72, or 128 channels)</p></li></ul><h3 id="Data-Mapping" tabindex="-1">Data Mapping <a class="header-anchor" href="#Data-Mapping" aria-label="Permalink to &quot;Data Mapping {#Data-Mapping}&quot;">​</a></h3><p><strong>EegFun.read_raw_data</strong> loads BioSemi data, then <strong>create_eegfun_data</strong> converts to native EegFun types:</p><ul><li><p>BioSemi BDF → <code>BiosemiData</code> (intermediate) → <code>ContinuousData</code> (EegFun)</p></li><li><p>Triggers extracted from Status channel</p></li><li><p>Layout coordinates added separately</p></li></ul><h2 id="Important-Notes" tabindex="-1">Important Notes <a class="header-anchor" href="#Important-Notes" aria-label="Permalink to &quot;Important Notes {#Important-Notes}&quot;">​</a></h2><h3 id="Layout-Files" tabindex="-1">Layout Files <a class="header-anchor" href="#Layout-Files" aria-label="Permalink to &quot;Layout Files {#Layout-Files}&quot;">​</a></h3><p>BioSemi doesn&#39;t embed electrode positions in the data file, so you must provide a matching layout. EegFun includes standard BioSemi layouts in <code>resources/layouts/biosemi/</code>:</p><ul><li><p><code>biosemi16.csv</code></p></li><li><p><code>biosemi32.csv</code></p></li><li><p><code>biosemi64.csv</code></p></li><li><p><code>biosemi72.csv</code> (64 + 8 external channels)</p></li><li><p><code>biosemi128.csv</code></p></li></ul><p>Choose the layout matching your recording setup.</p><h3 id="Trigger-Encoding" tabindex="-1">Trigger Encoding <a class="header-anchor" href="#Trigger-Encoding" aria-label="Permalink to &quot;Trigger Encoding {#Trigger-Encoding}&quot;">​</a></h3><p>BioSemi encodes triggers in a dedicated Status channel using binary encoding. EegFun automatically extracts these during import, making them available via <code>trigger_count()</code> and epoch extraction functions.</p><h2 id="Workflow-Summary" tabindex="-1">Workflow Summary <a class="header-anchor" href="#Workflow-Summary" aria-label="Permalink to &quot;Workflow Summary {#Workflow-Summary}&quot;">​</a></h2><p>This demo shows the complete BioSemi import workflow:</p><h3 id="1.-Load-Raw-BDF-Data" tabindex="-1">1. Load Raw BDF Data <a class="header-anchor" href="#1.-Load-Raw-BDF-Data" aria-label="Permalink to &quot;1. Load Raw BDF Data {#1.-Load-Raw-BDF-Data}&quot;">​</a></h3><ul><li><p>Use <code>read_raw_data()</code> with path to <code>.bdf</code> file</p></li><li><p>Automatic format detection based on file extension</p></li></ul><h3 id="2.-Prepare-Layout" tabindex="-1">2. Prepare Layout <a class="header-anchor" href="#2.-Prepare-Layout" aria-label="Permalink to &quot;2. Prepare Layout {#2.-Prepare-Layout}&quot;">​</a></h3><ul><li><p>Load appropriate BioSemi layout file</p></li><li><p>Convert polar coordinates to cartesian for visualization</p></li></ul><h3 id="3.-Create-EegFun-Data-Structure" tabindex="-1">3. Create EegFun Data Structure <a class="header-anchor" href="#3.-Create-EegFun-Data-Structure" aria-label="Permalink to &quot;3. Create EegFun Data Structure {#3.-Create-EegFun-Data-Structure}&quot;">​</a></h3><ul><li><p>Combine raw data with layout using <code>create_eegfun_data()</code></p></li><li><p>Results in <code>ContinuousData</code> ready for analysis</p></li></ul>',28)])])}const h=e(r,[["render",l]]);export{m as __pageData,h as default};
